export interface WaterTrail {
  id: string;
  /** Human-readable trail name. */
  name: string;
  /** DNR region: Southern, Eastern, Western, Central, etc. */
  region?: string;
  /** Designation: State / National / Local. */
  designation?: string;
  /** Trail type string from DNR (e.g. "Pt.s", "Loop"). */
  type?: string;
  /** DNR difficulty rating if provided. */
  difficulty?: string;
  /** Trail length in miles if provided. */
  distance?: number;
  /** Maryland county(ies) — freeform DNR string. */
  county?: string;
  /** Primary waterbody name. */
  waterbody?: string;
  /** Year DNR designated the trail. */
  yearCompleted?: string;
  /** Managing agency / organization. */
  managedBy?: string;
  /** DNR url for more information. */
  moreDetailUrl?: string;
  /** True if DNR publishes a printable map or guide. */
  hasMapOrGuide: boolean;
  /** One or more paths as arrays of [lng, lat] pairs. */
  paths: [number, number][][];
  /** Upstream DNR OBJECTID for debugging / resyncing. */
  dnrObjectId: number;
}

